void dei_rf_wake( Wake_Status wake_status )
{		
  	UInt32 base_time = DEI_RF_CK_1MHZ; 

	switch( wake_status )  
	{
		case s_WAKE : base_time = DEI_RF_CK_72MHZ ; break ;
		case s_SLEEP:
		{
			base_time = DEI_RF_CK_4MHZ;
		}
		break;
	}  

	dei_rf.time_rx_high_min = base_time * DEI_RF_RX_HIGH_MIN;
	dei_rf.time_rx_high_max = base_time * DEI_RF_RX_HIGH_MAX;
	dei_rf.time_rx_low_max  = base_time * DEI_RF_RX_LOW_MAX ;
    
}

